const input = $input.first().json;
let output = input.output || input.response || input.text || input.content || '';

try {
  const jsonMatch = output.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    const parsed = JSON.parse(jsonMatch[0]);
    if (parsed.needs_clarification) {
      return [{ json: { action: 'clarify', question: parsed.clarification_question } }];
    }
    return [{ json: { action: 'proceed', research: parsed } }];
  }
} catch (e) {}

return [{ json: { action: 'clarify', question: 'Failed to understand the request. Could you provide more details?' } }];

// MOCK: In reality, here you query Postgres:
