// const template = await $('Postgres').runQuery('SELECT structure FROM document_templates WHERE name = $1', [docType]);

const docType = $json.research.document_type || 'SDD';

const templates = {
  'SDD': '# System Design Document\n## 1. Overview\n## 2. Architecture\n## 3. API Design\n## 4. Data Model',
  'BRD': '# Business Requirements\n## 1. Objectives\n## 2. Scope\n## 3. Stakeholders'
};

return [{ json: { template: templates[docType] || templates['SDD'] } }];

